import java.util.BitSet;

class MyHashSet {
    private static final int MAX_KEY = 1_000_000;
    private final BitSet bits;

    public MyHashSet() {
        bits = new BitSet(MAX_KEY + 1);
    }

    public void add(int key) {
        bits.set(key);
    }

    public void remove(int key) {
        bits.clear(key);
    }

    public boolean contains(int key) {
        return bits.get(key);
    }
}

class MyHashSet {
    private static final int PAGE_BITS = 1024;
    private static final int WORD_BITS = 64;
    private static final int PAGE_COUNT = 978;
    private final long[][] pages;

    public MyHashSet() {
        pages = new long[PAGE_COUNT][];
    }

    public void add(int key) {
        ensurePage(key);
        int page = key / PAGE_BITS;
        int offset = key % PAGE_BITS;
        pages[page][offset / WORD_BITS] |= 1L << (offset % WORD_BITS);
    }

    public void remove(int key) {
        int page = key / PAGE_BITS;
        if (pages[page] == null) {
            return;
        }
        int offset = key % PAGE_BITS;
        pages[page][offset / WORD_BITS] &= ~(1L << (offset % WORD_BITS));
    }

    public boolean contains(int key) {
        int page = key / PAGE_BITS;
        if (pages[page] == null) {
            return false;
        }
        int offset = key % PAGE_BITS;
        return (pages[page][offset / WORD_BITS] & (1L << (offset % WORD_BITS))) != 0;
    }

    private void ensurePage(int key) {
        int page = key / PAGE_BITS;
        if (pages[page] == null) {
            pages[page] = new long[PAGE_BITS / WORD_BITS];
        }
    }
}

class MyHashSet {
    private static final int BUCKET_COUNT = 769;
    private final Node[] buckets;

    public MyHashSet() {
        buckets = new Node[BUCKET_COUNT];
    }

    public void add(int key) {
        int index = hash(key);
        for (Node node = buckets[index]; node != null; node = node.next) {
            if (node.key == key) {
                return;
            }
        }
        buckets[index] = new Node(key, buckets[index]);
    }

    public void remove(int key) {
        int index = hash(key);
        Node previous = null;
        Node node = buckets[index];
        while (node != null) {
            if (node.key == key) {
                if (previous == null) {
                    buckets[index] = node.next;
                } else {
                    previous.next = node.next;
                }
                return;
            }
            previous = node;
            node = node.next;
        }
    }

    public boolean contains(int key) {
        int index = hash(key);
        for (Node node = buckets[index]; node != null; node = node.next) {
            if (node.key == key) {
                return true;
            }
        }
        return false;
    }

    private int hash(int key) {
        return key % BUCKET_COUNT;
    }

    private static class Node {
        final int key;
        Node next;

        Node(int key, Node next) {
            this.key = key;
            this.next = next;
        }
    }
}

class MyHashSet {
    private static final int CAPACITY = 20011;
    private final int[] keys;
    private final byte[] state; // 0 = empty, 1 = occupied, 2 = deleted

    public MyHashSet() {
        keys = new int[CAPACITY];
        state = new byte[CAPACITY];
    }

    public void add(int key) {
        int slot = findSlotForInsert(key);
        keys[slot] = key;
        state[slot] = 1;
    }

    public void remove(int key) {
        int slot = findExistingSlot(key);
        if (slot != -1) {
            state[slot] = 2;
        }
    }

    public boolean contains(int key) {
        return findExistingSlot(key) != -1;
    }

    private int findSlotForInsert(int key) {
        int hash = key % CAPACITY;
        int firstDeleted = -1;
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step) % CAPACITY;
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
            if (state[index] == 2 && firstDeleted == -1) {
                firstDeleted = index;
            }
            if (state[index] == 0) {
                return firstDeleted == -1 ? index : firstDeleted;
            }
        }
        if (firstDeleted != -1) {
            return firstDeleted;
        }
        throw new IllegalStateException("hash set is full");
    }

    private int findExistingSlot(int key) {
        int hash = key % CAPACITY;
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step) % CAPACITY;
            if (state[index] == 0) {
                return -1;
            }
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
        }
        return -1;
    }
}
